#!/usr/bin/env python3
from __future__ import annotations
import base64,gzip,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[1]
METHODS=json.loads(gzip.decompress(base64.b64decode("")))

def replace_method(path: pathlib.Path, name: str, body: str) -> None:
    source=path.read_text(encoding="utf-8")
    match=re.search(r"\n(?P<indent>\s*)public function\s+"+re.escape(name)+r"\s*\([^)]*\)\s*:\s*void\s*\{",source)
    if not match: raise RuntimeError(f"Method not found: {path.relative_to(ROOT)}::{name}")
    brace=source.find("{",match.end()-1); depth=0; end=None
    for index in range(brace,len(source)):
        if source[index]=="{": depth+=1
        elif source[index]=="}":
            depth-=1
            if depth==0: end=index+1; break
    if end is None: raise RuntimeError(f"Unclosed method: {path.relative_to(ROOT)}::{name}")
    indent=match.group("indent")
    replacement="\n"+indent+"public function "+name+"(): void\n"+indent+"{"+body+"\n"+indent+"}"
    path.write_text(source[:match.start()]+replacement+source[end:],encoding="utf-8")

for key,body in METHODS.items():
    rel,name=key.split("::",1); replace_method(ROOT/rel,name,body)

p=ROOT/"tests/phpunit/bootstrap.php"; s=p.read_text(encoding="utf-8")
if "'password_confirmation' => $password" not in s:
    s=s.replace("            'password' => $password,\n            'csrf_token' => $csrf,","            'password' => $password,\n            'password_confirmation' => $password,\n            'csrf_token' => $csrf,")
p.write_text(s,encoding="utf-8")
p=ROOT/"scripts/validate_identity_behavior.php"; s=p.read_text(encoding="utf-8")
if "'password_confirmation'=>$password" not in s: s=s.replace("'password'=>$password]","'password'=>$password,'password_confirmation'=>$password]")
p.write_text(s,encoding="utf-8")
p=ROOT/"tests/phpunit/CustomerInboxSidebarContractTest.php"; s=p.read_text(encoding="utf-8").replace("/assets/js/personal-agent-chat-history.js?v=1.1.0","/assets/js/personal-agent-chat-history.js?v=1.2.0"); p.write_text(s,encoding="utf-8")
for rel in ["tests/phpunit/MobileAgentTabsTest.php","tests/phpunit/ProductionLiveUiHotfixTest.php"]:
    p=ROOT/rel; s=p.read_text(encoding="utf-8")
    s=s.replace("'data-create-menu-option=\"post\"'",'"\'option\' => \'post\'"')
    s=s.replace("'data-create-menu-option=\"microgift\"'",'"\'option\' => \'microgift\'"')
    p.write_text(s,encoding="utf-8")
print(f"Modernized {len(METHODS)} recovery contract methods and identity fixtures.")
